int A_length = A_next - A_curr;

int B_length = B_next - B_curr;

int total_iteration = ceil((C_length)/tile_size);          //total iteration

int C_completed = 0;

int A_consumed = 0;

int B_consumed = 0;

while(counter < total_iteration){

